def test_run_estimation(
        estimation_component_test_input,
        estimation_component_test_expected_output,
        estimation_component_test_expected_qa_output
    ):
    """Test that run_estimation returns the correct weighted df and QA df."""
    weighted_df, qa_df = run_estimation(
        df=estimation_component_test_input,
        a_wgt_band_col="a_wt_band",
        g_wgt_band_col="g_wt_band",
        ru_col="ruref",
        univ_count_col="N",
        aux_col="aux_var",
        univ_aux_col="uni_aux_var",
        incl_g_wts=True,
        g_wgt_type_col="g_wgt_type",
    )

    assert_frame_equal(weighted_df.round(4), estimation_component_test_expected_output.round(4), check_dtype=False, atol=1e-4)

    assert_frame_equal(qa_df.round(4), estimation_component_test_expected_qa_output.round(4), check_dtype=False, atol=1e-4)


def test_apply_weights(
        estimation_component_test_expected_output,
        estimation_component_test_expected_final_output
    ):
    """Test that apply_weights returns the correct final output."""
    final_output = apply_weights(
        df=estimation_component_test_expected_output.copy(),
        a_weight_columns=["Q1", "Q2", "Q3"],
        g_weight_columns=["Q1", "Q2"],
        question_col="question",
        value_col="value",
        calc_g_weight=True,
        round_val=4,
    )
    assert_frame_equal(final_output.round(4), estimation_component_test_expected_final_output.round(4), check_dtype=False, atol=1e-4)
